import { useState } from 'react';

export function UnderlineTabs() {
  const tabs = {{tabs}};
  const [active, setActive] = useState(tabs[0]);
  return (
    <div className="flex gap-6 border-b">
      {tabs.map((t) => (
        <button key={t} onClick={() => setActive(t)}
          className={`relative pb-3 text-sm font-medium ${active === t ? 'text-blue-600' : 'text-gray-500 hover:text-gray-900'}`}>
          {t}
          {active === t && <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600" />}
        </button>
      ))}
    </div>
  );
}
